/** Narrowing bound for one argument. */
export type ArgumentBound = {
  minimum?: number;
  maximum?: number;
  enum?: unknown[];
};

export type PolicyPrincipal = {
  tokens?: Digest[];
  uids?: number[];
  scopes: Scope[];
  bounds?: {
    [key: string]: {
      [key: string]: ArgumentBound;
    };
  };
};

/** Gateway authorization policy document (13-security.md 13.2). */
export type GatewayPolicy = {
  principals: {
    [key: string]: PolicyPrincipal;
  };
};

export type AgentFindInput = {
  /** Words to match in names, summaries and tags. */
  text?: string;
  /** Capability id, or prefix ending in .* */
  capability?: string;
  tag?: Tag;
  status?: DeviceStatus;
  cursor?: Cursor;
};

export type AgentDescribeInput = {
  device_id: DeviceId;
};

export type AgentReadInput = {
  device_id: DeviceId;
  property: Name;
  /** Maximum acceptable age. */
  max_age_ms?: number;
  /** Require a new measurement. */
  fresh?: boolean;
};

export type AgentInvokeInput = {
  device_id: DeviceId;
  action: Name;
  /** Arguments per the action's input schema; numbers in the declared unit, or {value, unit}. */
  arguments: Record<string, unknown>;
  /** Optional idempotency key. Reuse the same key with identical arguments to retry safely. */
  operation_key?: AgentOperationKey;
  /** Milliseconds to wait for the outcome (default 5000, max 60000). */
  wait_ms?: number;
  /** Fail unless the effect is verified by measurement. */
  require_verified?: boolean;
};

export type AgentOperationInput = {
  operation_id: ServerId;
  /** Milliseconds to wait for the outcome (default 5000, max 60000). */
  wait_ms?: number;
};

export type AgentCancelInput = {
  operation_id: ServerId;
  reason?: string;
};

export type AgentStopInput = {
  device_ids?: DeviceId[];
  all?: true;
  reason: string;
};

export type AgentRunProgramInput = {
  program?: Program;
  program_digest?: Digest;
  arguments: Record<string, unknown>;
  /** Optional idempotency key. Reuse the same key with identical arguments to retry safely. */
  operation_key?: AgentOperationKey;
  /** Milliseconds to wait for the outcome (default 5000, max 60000). */
  wait_ms?: number;
};

/** Structured content of bhms_find. */
export type AgentFindData = {
  devices: DeviceSummary[];
  programs?: ProgramInfo[];
  nextCursor?: Cursor;
};

/** Result of a function-tool call: summary plus data or error. */
export type AgentFunctionResult = {
  summary: string;
  /** bhms_describe only: the compact signature block of BHMS-AGT-013 (function tools cannot carry it after the one-line summary). */
  signature?: string;
  data?: Record<string, unknown>;
  error?: OperationError;
};

/** Every BHMS method: its params and result types and whether it is core or capability-gated. */
export interface Methods {
  "server/discover": { params: DiscoverParams; result: DiscoverResult };
  "devices/list": { params: DevicesListParams; result: DevicesListResult };
  "devices/describe": { params: DevicesDescribeParams; result: DevicesDescribeResult };
  "properties/read": { params: PropertiesReadParams; result: PropertiesReadResult };
  "actions/invoke": { params: ActionsInvokeParams; result: ActionsInvokeResult };
  "operations/get": { params: OperationsGetParams; result: OperationsGetResult };
  "operations/wait": { params: OperationsWaitParams; result: OperationsWaitResult };
  "operations/list": { params: OperationsListParams; result: OperationsListResult };
  "operations/cancel": { params: OperationsCancelParams; result: OperationsCancelResult };
  "stop": { params: StopParams; result: StopResult };
  "subscriptions/listen": { params: SubscriptionsListenParams; result: SubscriptionsListenResult };
  "leases/acquire": { params: LeasesAcquireParams; result: LeasesAcquireResult };
  "leases/renew": { params: LeasesRenewParams; result: LeasesRenewResult };
  "leases/release": { params: LeasesReleaseParams; result: LeasesReleaseResult };
  "events/read": { params: EventsReadParams; result: EventsReadResult };
  "programs/run": { params: ProgramsRunParams; result: ProgramsRunResult };
  "programs/register": { params: ProgramsRegisterParams; result: ProgramsRegisterResult };
  "programs/get": { params: ProgramsGetParams; result: ProgramsGetResult };
  "programs/list": { params: ProgramsListParams; result: ProgramsListResult };
}

